def term_count(term, text):
    """Case-insensitive whole-word fixed-string count — the semantics of
    `rg -i -w -F --count-matches`. Pure stdlib: no ripgrep binary on this box."""
    pat = re.compile(r"(?<![A-Za-z0-9_])" + re.escape(term) + r"(?![A-Za-z0-9_])", re.IGNORECASE)
    return len(pat.findall(text))


def retrieve(task_text, facts, facts_dir, k):
    terms = tokenize(task_text)
    scores = {}  # file -> [distinct terms, total matches]
    for f in facts:
        searchable = f["text"] + "\n" + f["paths"] + "\n" + f["id"]
        for t in terms:
            n = term_count(t, searchable)
            if n:
                s = scores.setdefault(f["file"], [0, 0])
                s[0] += 1
                s[1] += n
    by_file = {f["file"]: f for f in facts}
    ranked = sorted(
        scores,
        key=lambda f: (-scores[f][0], -scores[f][1], f),
    )
    return [by_file[f] for f in ranked[:k]]

