8	// facts_eval_arms.go provides the three retrieval structures the Appendix-D A/B
9	// compares, behind one retrievalArm signature so the eval loop is arm-agnostic:
10	//
11	//	flat    — (a) the shipped Phase-A ranker over all branch facts.
12	//	scoped  — (b) locus-scoped: when the query names code, rank only the facts
13	//	          whose locus overlaps it (Appendix D's "the 8 facts about the package
14	//	          you're editing"); otherwise fall back to flat.
15	//	scoped-floor — (b') scoped with a recall floor: the locus-scoped facts rank
16	//	          first, then flat-ranked facts backfill up to k. Recovers the recall
17	//	          a hard locus filter drops while keeping the scoped facts on top.
18	//	outline — (c) outline-scoped: rank within the subtree of the best-matching
19	//	          outline node (progressive disclosure); on the root it equals flat.
20	//
21	// Each arm returns the surfaced facts; the eval scores them identically.
22	type retrievalArm func(facts []factRecord, query string, k int, rr *semanticReranker) []factRecord
23	
24	func selectRetrievalArm(name string) (retrievalArm, error) {
25		switch name {
26		case "", "flat":
27			return flatArm, nil
28		case "scoped":
29			return scopedArm, nil
30		case "scoped-floor":
31			return scopedFloorArm, nil
32		case "outline":
33			return outlineArm, nil
34		default:
35			return nil, fmt.Errorf("--arm must be flat, scoped, scoped-floor, or outline")
36		}
37	}
