43	// scopedArm narrows to the facts whose locus the query names before ranking.
44	// When the query has no code locus, or nothing matches, it falls back to flat so
45	// a conceptual query is never starved to zero.
46	func scopedArm(facts []factRecord, query string, k int, rr *semanticReranker) []factRecord {
47		scoped := filterFactsByLocus(facts, query)
48		if len(scoped) > 0 && len(scoped) < len(facts) {
49			return rankFactsFused(scoped, query, k, false, rr)
50		}
51		return rankFactsFused(facts, query, k, false, rr)
52	}
53	
54	// scopedFloorArm puts the locus-scoped facts first, then backfills with
55	// flat-ranked facts (not already surfaced) up to k. It targets the recall cost
56	// of the hard scoped filter — relevant facts that don't name the queried code —
57	// while keeping the high-precision locus matches at the top. When the query has
58	// no code locus (or every fact matches) it is exactly flat.
59	func scopedFloorArm(facts []factRecord, query string, k int, rr *semanticReranker) []factRecord {
60		scoped := filterFactsByLocus(facts, query)
61		if len(scoped) == 0 || len(scoped) == len(facts) {
62			return rankFactsFused(facts, query, k, false, rr)
63		}
64		out := rankFactsFused(scoped, query, k, false, rr)
65		if len(out) >= k {
66			return out
67		}
68		seen := make(map[string]struct{}, len(out))
69		for _, f := range out {
70			seen[f.ID] = struct{}{}
71		}
72		for _, f := range rankFactsFused(facts, query, k, false, rr) {
73			if len(out) >= k {
74				break
75			}
76			if _, ok := seen[f.ID]; ok {
77				continue
78			}
79			out = append(out, f)
80			seen[f.ID] = struct{}{}
81		}
82		return out
83	}
