86	// the "load the relevant subtree, not the whole branch" hypothesis. On the
87	// locus-sparse root (where most facts home) the subtree is the whole branch, so
88	// it degenerates to flat; that degeneration is itself a measured result.
89	func outlineArm(facts []factRecord, query string, k int, rr *semanticReranker) []factRecord {
90		ranked := rankFactsFused(facts, query, max(k*3, k), false, rr)
91		if len(ranked) == 0 {
92			return nil
93		}
94		outline := buildFactOutlineTree("", facts, time.Time{})
95		home := factHomeKey(ranked[0])
96		ids := subtreeFactIDs(outline, home)
97		if len(ids) == 0 || len(ids) == len(facts) {
98			return rankFactsFused(facts, query, k, false, rr)
99		}
100		subset := make([]factRecord, 0, len(ids))
101		for _, f := range facts {
102			if _, ok := ids[f.ID]; ok {
103				subset = append(subset, f)
104			}
105		}
106		return rankFactsFused(subset, query, k, false, rr)
107	}
