109	// subtreeFactIDs collects the fact ids at and beneath an outline node.
110	func subtreeFactIDs(outline factOutline, key string) map[string]struct{} {
111		ids := map[string]struct{}{}
112		var walk func(k string)
113		walk = func(k string) {
114			n, ok := outline.Nodes[k]
115			if !ok {
116				return
117			}
118			for _, id := range n.LeafFactIDs {
119				ids[id] = struct{}{}
120			}
121			for _, c := range n.Children {
122				walk(c)
123			}
124		}
125		walk(key)
