// snapprof wraps the entire-graph CLI with a CPU profile for local
// performance investigation. Not shipped; lives only in this working clone.
package main

import (
	"fmt"
	"os"
	"runtime/pprof"

	"github.com/entireio/entire-graph/internal/cli"
)

func main() {
	f, err := os.Create(os.Getenv("SNAPPROF_OUT"))
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := pprof.StartCPUProfile(f); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	runErr := cli.Execute("dev-prof", os.Args[1:])
	pprof.StopCPUProfile()
	_ = f.Close()
	if runErr != nil {
		fmt.Fprintln(os.Stderr, runErr.Error())
		os.Exit(1)
	}
}

